const staticData = $getWorkflowStaticData('global');
if (!staticData.inProgress) staticData.inProgress = {};

// .all()[$itemIndex] thay vì .item hay .first(): .item có thể crash nếu
// pairedItem bị mất qua node HTTP phía sau; .first() luôn lấy subfolder ĐẦU
// TIÊN bất kể đang xử lý subfolder nào — sai khi có ≥2 subfolder có video mới
// trong cùng 1 lần chạy (gây lẫn dữ liệu giữa các cuộc họp khác nhau).
// .all()[$itemIndex] lấy đúng theo vị trí, an toàn trong mọi trường hợp.
const subfolderId = $('1b. Split Subfolders').all()[$itemIndex].json.id;
const subfolderName = $('1b. Split Subfolders').all()[$itemIndex].json.name;
const subfolderCreatedTime = $('1b. Split Subfolders').all()[$itemIndex].json.createdTime;

// Safety net: forget any subfolder we started but never finished (crashed run) after 1h
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.inProgress)) {
  if (now - ts > 60 * 60 * 1000) delete staticData.inProgress[id];
}

// Already picked up by an earlier still-running execution (pipeline can take
// longer than the 5-minute poll interval) — skip to avoid double-processing.
if (staticData.inProgress[subfolderId]) return [];

const files = $json.files || [];
const video = files.find(f => (f.mimeType || '').startsWith('video/'));
if (!video) return []; // subfolder exists but recording not uploaded yet — wait for next poll

staticData.inProgress[subfolderId] = now;

return [{ json: { id: video.id, name: video.name, mimeType: video.mimeType, subfolderId, subfolderName, subfolderCreatedTime } }];

// Dùng $itemIndex + .all()[$itemIndex] thay vì .item hay .first():
// - .item crash khi '1e' (HTTP, có onError) làm mất liên kết pairedItem.
// - .first() luôn lấy item ĐẦU TIÊN của toàn node, bất kể đang xử lý video
//   nào — nếu 2 video được xử lý cùng 1 lần chạy (2 subfolder có video mới
//   cùng lúc), dữ liệu sẽ bị LẪN giữa 2 cuộc họp khác nhau (bug thật đã xảy ra).
// .all()[$itemIndex] lấy đúng theo VỊ TRÍ item hiện tại, không phụ thuộc
// pairedItem, và không bị lẫn khi có nhiều video cùng lúc.
const video = $('1d. Find New Video').all()[$itemIndex].json;
const subfolderCreated = new Date(video.subfolderCreatedTime).getTime();
const events = ($json && $json.items) || [];

// Match by the Calendar event's own "created" timestamp, not its scheduled start
// time — quick/test meetings often share the same default start time (e.g. many
// events all starting 16:00), which makes start-time proximity ambiguous. The app
// creates the Calendar event at the same moment it creates the Meeting DB row, so
// "created" tracks the subfolder's creation time far more tightly (seconds, not
// hours) and reliably picks the right event even among same-start-time siblings.
let best = null, bestDiff = Infinity;
for (const e of events) {
  if (!e.hangoutLink || !e.created) continue;
  const diff = Math.abs(new Date(e.created).getTime() - subfolderCreated);
  if (diff < bestDiff) { bestDiff = diff; best = e; }
}

return [{
  json: {
    id: video.id,
    name: video.name,
    mimeType: video.mimeType,
    subfolderId: video.subfolderId,
    subfolderName: video.subfolderName,
    realMeetUrl: best ? best.hangoutLink : null,
    realStartDateTime: best?.start?.dateTime || null,
    realEndDateTime: best?.end?.dateTime || null
  }
}];

const fs = require('fs');
const { execSync } = require('child_process');

const execId = $execution.id;
const inputPath = `/tmp/input_${execId}.mp4`;
const outputPath = `/tmp/output_${execId}.mp3`;

const gdriveFileId = $('1f. Extract Meet Link').all()[$itemIndex].json.id;
const subfolderId = $('1f. Extract Meet Link').all()[$itemIndex].json.subfolderId;
const realMeetUrl = $('1f. Extract Meet Link').all()[$itemIndex].json.realMeetUrl;
const realStartDateTime = $('1f. Extract Meet Link').all()[$itemIndex].json.realStartDateTime;
const realEndDateTime = $('1f. Extract Meet Link').all()[$itemIndex].json.realEndDateTime;

const binaryId = $input.first().binary.data.id;

if (!binaryId || !binaryId.includes(':')) {
  throw new Error('Invalid binaryId: ' + binaryId);
}

const relativePath = binaryId.split(':')[1];
const binaryFile = `/root/.n8n/binaryData/${relativePath}`;

if (!fs.existsSync(binaryFile)) {
  throw new Error('Binary file not found at: ' + binaryFile);
}

execSync(`cp "${binaryFile}" "${inputPath}"`);

const size = fs.statSync(inputPath).size;
if (size === 0) throw new Error('File saved but size is 0 bytes');

return [{ json: { saved: true, sizeMB: Math.round(size / 1048576), execId, inputPath, outputPath, gdriveFileId, subfolderId, realMeetUrl, realStartDateTime, realEndDateTime } }];

const { spawn } = require('child_process');
const meta = $input.first().json;
return new Promise((resolve, reject) => {
  const proc = spawn('ffmpeg', ['-y','-i',meta.inputPath,'-vn','-acodec','libmp3lame','-ab','64k','-ar','16000','-ac','1','-threads','4',meta.outputPath]);
  let stderr = '';
  proc.stderr.on('data', (d) => { stderr += d.toString(); });
  proc.on('close', (code) => { if (code === 0) resolve([{ json: { success: true, inputPath: meta.inputPath, outputPath: meta.outputPath, gdriveFileId: meta.gdriveFileId } }]); else reject(new Error(`FFmpeg failed (code ${code}): ${stderr.slice(-500)}`)); });
  proc.on('error', (err) => reject(new Error(`FFmpeg spawn error: ${err.message}`)));
});

const fs = require('fs');
const meta = $input.first().json;
const mp3Buffer = fs.readFileSync(meta.outputPath);
try { fs.unlinkSync(meta.inputPath); } catch(e) {}
try { fs.unlinkSync(meta.outputPath); } catch(e) {}
const binaryOutput = await this.helpers.prepareBinaryData(mp3Buffer, 'audio.mp3', 'audio/mpeg');
return [{ json: { converted: true, gdriveFileId: meta.gdriveFileId }, binary: { data: binaryOutput } }];

const transcript = $input.first().json;
const gdriveFileId = $('2b. Save to /tmp').all()[$itemIndex].json.gdriveFileId;
let fileName = 'Unknown';
try { fileName = $('1d. Find New Video').all()[$itemIndex].json.name || 'Unknown'; } catch(e) { fileName = 'Video Recording'; }
let formattedTranscript = '';
let speakerCount = 0;
if (transcript.utterances && transcript.utterances.length > 0) {
  const speakers = [...new Set(transcript.utterances.map(u => u.speaker))];
  speakerCount = speakers.length;
  for (const u of transcript.utterances) {
    const min = Math.floor(u.start / 60000);
    const sec = Math.floor((u.start % 60000) / 1000);
    const ts = `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
    formattedTranscript += `[${ts}] ${u.text}\n\n`;
  }
} else { formattedTranscript = transcript.text || 'Không có nội dung.'; speakerCount = 1; }
const durationMin = Math.round((transcript.audio_duration || 0) / 60);
const wordCount = (transcript.text || '').split(/\s+/).length;
const MAX_CHARS = 80000;
let trimmed = formattedTranscript;
if (formattedTranscript.length > MAX_CHARS) trimmed = formattedTranscript.substring(0, MAX_CHARS) + '\n\n[... bị cắt do quá dài ...]';
let meetingDate = '';
const dateMatch = fileName.match(/(\d{4}-\d{2}-\d{2})/);
if (dateMatch) meetingDate = dateMatch[1];
return [{ json: { fileName, meetingDate, transcript: trimmed, fullText: transcript.text || '', duration: durationMin, speakerCount, wordCount, transcriptId: transcript.id, gdriveFileId } }];

// .all()[$itemIndex] thay vì .first() — tránh lẫn dữ liệu giữa nhiều video
// được xử lý cùng lúc trong 1 lần chạy (xem giải thích chi tiết ở node 1f).
const meta = $('8. Format Transcript').all()[$itemIndex].json;
const claudeResponse = $input.first().json;
const gdriveFileId = meta.gdriveFileId;

let fullSummary = '';
try { fullSummary = claudeResponse.choices[0].message.content; } catch(e) { fullSummary = 'Không lấy được summary.'; }

// --- Extract bracketed sections [HEADER] [TỔNG QUAN] [PROJECTS] [VẤN ĐỀ & RỦI RO] [BƯỚC TIẾP THEO]
function getSection(text, name, nextNames) {
  const start = text.indexOf('[' + name + ']');
  if (start === -1) return '';
  const after = start + name.length + 2;
  let end = text.length;
  for (const n of nextNames) {
    const idx = text.indexOf('[' + n + ']', after);
    if (idx !== -1 && idx < end) end = idx;
  }
  const dashIdx = text.indexOf('\n---', after);
  if (dashIdx !== -1 && dashIdx < end) end = dashIdx;
  return text.substring(after, end).trim();
}

const headerBlock   = getSection(fullSummary, 'HEADER',          ['TỔNG QUAN','PROJECTS','VẤN ĐỀ & RỦI RO','BƯỚC TIẾP THEO']);
const overview      = getSection(fullSummary, 'TỔNG QUAN',       ['PROJECTS','VẤN ĐỀ & RỦI RO','BƯỚC TIẾP THEO']);
const projectsBlock = getSection(fullSummary, 'PROJECTS',        ['VẤN ĐỀ & RỦI RO','BƯỚC TIẾP THEO']);
const issues        = getSection(fullSummary, 'VẤN ĐỀ & RỦI RO', ['BƯỚC TIẾP THEO']);
const nextSteps     = getSection(fullSummary, 'BƯỚC TIẾP THEO', []);

function getField(block, key) {
  const escKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('^\\s*' + escKey + '\\s*:\\s*(.+)$', 'mi');
  const m = block.match(re);
  return m ? m[1].trim() : 'Không đề cập';
}

const teamName  = getField(headerBlock, 'Team');
const summarist = getField(headerBlock, 'Người summary');

// Parse project blocks
const projects = [];
const projRe = /===PROJECT===([\s\S]*?)===END===/g;
let pm;
while ((pm = projRe.exec(projectsBlock)) !== null) {
  const b = pm[1];
  projects.push({
    name:     getField(b, 'Tên'),
    taskCha:  getField(b, 'Task cha'),
    priority: getField(b, 'Priority'),
    manday:   getField(b, 'Manday Budget'),
    owner:    getField(b, 'Owner'),
    deadline: getField(b, 'Deadline'),
    kpi:      getField(b, 'KPI / Output')
  });
}

// --- Week label
function getWeekNumber(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}
const now = new Date();
const weekLabel = `Tuần ${getWeekNumber(now)}`;

// --- Meeting date/time (ISO date for API + display string)
// Ưu tiên giờ THẬT từ Calendar Event đã match ở node 1f (Google trả về
// start.dateTime/end.dateTime chính xác đến giây, kèm timezone) — đáng tin
// cậy hơn hẳn regex đoán giờ từ tên file recording, vốn không khớp với định
// dạng tên file thật của Google Meet ("{Title} ({date} {time} {tz}).mp4",
// dùng dấu ':' chứ không phải '-') nên trước giờ luôn rơi vào fallback 09:00.
const realStart = $('2b. Save to /tmp').all()[$itemIndex].json.realStartDateTime;

let isoDate, startTimeStr, meetingDateTime;
if (realStart) {
  const d = new Date(realStart);
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false
  }).formatToParts(d).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
  isoDate = `${parts.year}-${parts.month}-${parts.day}`;
  startTimeStr = `${parts.hour}:${parts.minute}`;
  meetingDateTime = `${isoDate} ${startTimeStr}`;
} else {
  // Fallback: regex tên file (thường sẽ không khớp) rồi tới thời điểm hiện tại
  isoDate = meta.meetingDate || now.toISOString().slice(0, 10);
  const timeMatch = (meta.fileName || '').match(/(\d{2})-(\d{2})-(\d{2})(?:\.mp4|\.webm)?$/i);
  startTimeStr = timeMatch ? `${timeMatch[1]}:${timeMatch[2]}` : null;
  meetingDateTime = isoDate;
  if (timeMatch) meetingDateTime += ` ${timeMatch[1]}:${timeMatch[2]}`;
  if (!meta.meetingDate) meetingDateTime = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
}

// --- Tab name
const dateParts = isoDate.split('-');
const ymd = `${dateParts[0].slice(2)}-${dateParts[1]}-${dateParts[2]}`;
const ts = now.toISOString().slice(11, 19).replace(/:/g, '');
const tabName = `${ymd} - ${ts}`;

const videoLink = `https://drive.google.com/file/d/${gdriveFileId}/view`;
// Google Meet recording files are named "{Calendar Event Title} ({date} {time} {timezone}).mp4"
// — strip that trailing "(...)"+extension so the title exact-matches the meeting created
// on the web (backend matches by title+date to update the existing meeting instead of
// creating a duplicate detached from the real meet.google.com link).
const rawFileName = meta.fileName || 'Không rõ';
const cleanedTitle = rawFileName.replace(/\s*\([^)]*\)(\.[a-zA-Z0-9]+)?$/, '').trim();
const meetingName = cleanedTitle || rawFileName;

let shortSummary = overview || '';
if (shortSummary.length > 300) shortSummary = shortSummary.substring(0, 297) + '...';

// --- Build sheet rows (2 columns: label, value)
const rows = [];

// Title row
rows.push([`MEETING SUMMARY - ${meetingName}`, '']);
rows.push(['', '']);

// Header info table
rows.push(['Ngày họp',           meetingDateTime]);
rows.push(['Tuần',               weekLabel]);
rows.push(['Thời lượng',         `${meta.duration} phút`]);
rows.push(['Link record',        videoLink]);
rows.push(['Team',               teamName]);
rows.push(['Người summary',      summarist]);
rows.push(['Số người tham gia',  `${meta.speakerCount}`]);
rows.push(['', '']);

// Overview
rows.push(['TỔNG QUAN', '']);
rows.push([overview || 'Không có thông tin', '']);
rows.push(['', '']);

// Projects
rows.push(['TASK CHA ĐÃ CHỐT', '']);

if (projects.length === 0) {
  rows.push(['Không có project nào được chốt trong cuộc họp.', '']);
} else {
  projects.forEach((p, i) => {
    rows.push([`${i + 1}. Project: `, '']);   // tên project để trống cho user tự điền
    rows.push(['Task cha',       p.taskCha]);
    rows.push(['Priority',       p.priority]);
    rows.push(['Manday Budget',  p.manday]);
    rows.push(['Owner',          p.owner]);
    rows.push(['Deadline',       p.deadline]);
    rows.push(['KPI / Output',   p.kpi]);
    rows.push(['', '']);
  });
}

// Issues
rows.push(['VẤN ĐỀ & RỦI RO', '']);
const issuesList = (issues || 'Không có').split('\n').map(l => l.trim()).filter(Boolean);
if (issuesList.length === 0) {
  rows.push(['Không có', '']);
} else {
  issuesList.forEach((item, i) => {
    const clean = item.replace(/^\d+\.\s*/, '').trim();
    rows.push([`${i + 1}. ${clean}`, '']);
  });
}
rows.push(['', '']);

// Next steps
rows.push(['BƯỚC TIẾP THEO', '']);
const nextList = (nextSteps || 'Không có').split('\n').map(l => l.trim()).filter(Boolean);
if (nextList.length === 0) {
  rows.push(['Không có', '']);
} else {
  nextList.forEach((item, i) => {
    const clean = item.replace(/^\d+\.\s*/, '').trim();
    rows.push([`${i + 1}. ${clean}`, '']);
  });
}

return [{
  json: {
    tabName,
    sheetRows: rows,
    weekLabel,
    meetingDateTime,
    meetingName,
    duration: `${meta.duration} phút`,
    videoLink,
    shortSummary,
    teamName,
    summarist,
    speakerCount: meta.speakerCount,
    projectCount: projects.length,
    sheetId: '12lhXE87vYPpYwXjT63f0GqBLJKSF49f5hwN5iJ0w4IY',
    gdriveFileId,
    // --- Added for webhook push to Plane.so backend (POST /api/meetings/webhook/n8n-summary) ---
    meetingDateIso: isoDate,
    startTimeStr,
    overview,
    issuesArr: issuesList.length && issuesList[0] !== 'Không có' ? issuesList.map(i => i.replace(/^\d+\.\s*/, '')) : [],
    nextArr: nextList.length && nextList[0] !== 'Không có' ? nextList.map(i => i.replace(/^\d+\.\s*/, '')) : [],
    projectsArr: projects
  }
}];

const data = $('14a. Parse Summary').all()[$itemIndex].json;
const createTabResponse = $('14b. Create Tab').all()[$itemIndex].json;

let tabGid = 0;
try { tabGid = createTabResponse.replies[0].addSheet.properties.sheetId; } catch(e) { tabGid = 0; }

const rows = data.sheetRows;
const reqs = [];

// Column widths
[{s:0,e:1,w:170},{s:1,e:2,w:720}].forEach(c => {
  reqs.push({ updateDimensionProperties: { range: { sheetId: tabGid, dimension: 'COLUMNS', startIndex: c.s, endIndex: c.e }, properties: { pixelSize: c.w }, fields: 'pixelSize' } });
});

const SECTION_HEADERS = ['TỔNG QUAN','TASK CHA ĐÃ CHỐT','VẤN ĐỀ & RỦI RO','BƯỚC TIẾP THEO'];
const FIELD_LABELS = ['Ngày họp','Tuần','Thời lượng','Link record','Team','Người summary','Số người tham gia','Task cha','Priority','Manday Budget','Owner','Deadline','KPI / Output'];

const titleColor   = { red: 0.13, green: 0.27, blue: 0.47 };
const sectionColor = { red: 0.20, green: 0.33, blue: 0.53 };
const projectBg    = { red: 0.97, green: 0.92, blue: 0.92 };
const projectFg    = { red: 0.75, green: 0.22, blue: 0.17 };
const fieldLabelBg = { red: 0.95, green: 0.95, blue: 0.97 };
const white        = { red: 1, green: 1, blue: 1 };

// 3 cấp Priority: Critical / High / Normal
const priorityColors = {
  critical: { bg: { red: 0.96, green: 0.78, blue: 0.78 }, fg: { red: 0.60, green: 0.10, blue: 0.10 } },
  high:     { bg: { red: 1.00, green: 0.88, blue: 0.70 }, fg: { red: 0.70, green: 0.35, blue: 0.05 } },
  normal:   { bg: { red: 0.85, green: 0.92, blue: 0.85 }, fg: { red: 0.20, green: 0.50, blue: 0.20 } }
};

function mergeAndFormat(rowIdx, bg, fg, fontSize, height) {
  reqs.push({ repeatCell: { range: { sheetId: tabGid, startRowIndex: rowIdx, endRowIndex: rowIdx + 1, startColumnIndex: 0, endColumnIndex: 2 }, cell: { userEnteredFormat: { backgroundColor: bg, textFormat: { bold: true, fontSize, foregroundColor: fg }, horizontalAlignment: 'LEFT', verticalAlignment: 'MIDDLE', padding: { top: 5, bottom: 5, left: 10 } } }, fields: 'userEnteredFormat(backgroundColor,textFormat,horizontalAlignment,verticalAlignment,padding)' } });
  reqs.push({ mergeCells: { range: { sheetId: tabGid, startRowIndex: rowIdx, endRowIndex: rowIdx + 1, startColumnIndex: 0, endColumnIndex: 2 }, mergeType: 'MERGE_ALL' } });
  if (height) reqs.push({ updateDimensionProperties: { range: { sheetId: tabGid, dimension: 'ROWS', startIndex: rowIdx, endIndex: rowIdx + 1 }, properties: { pixelSize: height }, fields: 'pixelSize' } });
}

rows.forEach((row, i) => {
  const a = (row[0] || '').toString();
  const b = (row[1] || '').toString();

  if (a.startsWith('MEETING SUMMARY')) {
    mergeAndFormat(i, titleColor, white, 13, 38);
  } else if (SECTION_HEADERS.includes(a)) {
    mergeAndFormat(i, sectionColor, white, 11, 30);
  } else if (/^\d+\.\s*Project:/.test(a)) {
    mergeAndFormat(i, projectBg, projectFg, 11, 28);
  } else if (FIELD_LABELS.includes(a)) {
    // Label cell (col A)
    reqs.push({ repeatCell: { range: { sheetId: tabGid, startRowIndex: i, endRowIndex: i + 1, startColumnIndex: 0, endColumnIndex: 1 }, cell: { userEnteredFormat: { backgroundColor: fieldLabelBg, textFormat: { bold: true, fontSize: 10 }, horizontalAlignment: 'LEFT', verticalAlignment: 'TOP', padding: { top: 4, bottom: 4, left: 8 } } }, fields: 'userEnteredFormat(backgroundColor,textFormat,horizontalAlignment,verticalAlignment,padding)' } });
    // Value cell (col B)
    reqs.push({ repeatCell: { range: { sheetId: tabGid, startRowIndex: i, endRowIndex: i + 1, startColumnIndex: 1, endColumnIndex: 2 }, cell: { userEnteredFormat: { textFormat: { fontSize: 10 }, horizontalAlignment: 'LEFT', verticalAlignment: 'TOP', padding: { top: 4, bottom: 4, left: 8 } } }, fields: 'userEnteredFormat(textFormat,horizontalAlignment,verticalAlignment,padding)' } });

    if (a === 'Priority') {
      // Conditional formatting: màu auto lên khi user gõ/sửa giá trị
      const rowA1 = i + 1;
      Object.entries(priorityColors).forEach(([key, c]) => {
        reqs.push({
          addConditionalFormatRule: {
            rule: {
              ranges: [{ sheetId: tabGid, startRowIndex: i, endRowIndex: i + 1, startColumnIndex: 1, endColumnIndex: 2 }],
              booleanRule: {
                condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: `=LOWER(TRIM(B${rowA1}))="${key}"` }] },
                format: { backgroundColor: c.bg, textFormat: { bold: true, foregroundColor: c.fg } }
              }
            }
          }
        });
      });
    }
  } else if (a && !b) {
    // Paragraph / list-item → merge col A + B cho full-width
    reqs.push({ repeatCell: { range: { sheetId: tabGid, startRowIndex: i, endRowIndex: i + 1, startColumnIndex: 0, endColumnIndex: 2 }, cell: { userEnteredFormat: { textFormat: { fontSize: 10 }, horizontalAlignment: 'LEFT', verticalAlignment: 'TOP', padding: { top: 4, bottom: 4, left: 8 }, wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat(textFormat,horizontalAlignment,verticalAlignment,padding,wrapStrategy)' } });
    reqs.push({ mergeCells: { range: { sheetId: tabGid, startRowIndex: i, endRowIndex: i + 1, startColumnIndex: 0, endColumnIndex: 2 }, mergeType: 'MERGE_ALL' } });
  }
});

// Wrap text mọi cell
reqs.push({ repeatCell: { range: { sheetId: tabGid, startRowIndex: 0, endRowIndex: rows.length, startColumnIndex: 0, endColumnIndex: 2 }, cell: { userEnteredFormat: { wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat.wrapStrategy' } });

// Border xám nhạt
reqs.push({ updateBorders: { range: { sheetId: tabGid, startRowIndex: 0, endRowIndex: rows.length, startColumnIndex: 0, endColumnIndex: 2 }, top: { style: 'SOLID', width: 1, color: { red: 0.85, green: 0.85, blue: 0.85 } }, bottom: { style: 'SOLID', width: 1, color: { red: 0.85, green: 0.85, blue: 0.85 } }, left: { style: 'SOLID', width: 1, color: { red: 0.85, green: 0.85, blue: 0.85 } }, right: { style: 'SOLID', width: 1, color: { red: 0.85, green: 0.85, blue: 0.85 } }, innerHorizontal: { style: 'SOLID', width: 1, color: { red: 0.92, green: 0.92, blue: 0.92 } }, innerVertical: { style: 'SOLID', width: 1, color: { red: 0.92, green: 0.92, blue: 0.92 } } } });

return [{ json: { formatRequests: reqs, sheetId: data.sheetId, tabGid, gdriveFileId: data.gdriveFileId } }];

const data = $('14a. Parse Summary').all()[$itemIndex].json;
const buildFormat = $('14c2. Build Format').all()[$itemIndex].json;

const summaryLink = `https://docs.google.com/spreadsheets/d/${buildFormat.sheetId}/edit#gid=${buildFormat.tabGid}`;

return [{
  json: {
    week: data.weekLabel,
    meetingDate: data.meetingDateTime,
    team: data.teamName || 'Không đề cập',
    meetingName: data.meetingName,
    duration: data.duration,
    videoLink: data.videoLink,
    summary: data.shortSummary,
    summaryLink,
    gdriveFileId: data.gdriveFileId
  }
}];

const meta = $('14a. Parse Summary').all()[$itemIndex].json;
const errorData = $input.first().json;

const now = new Date();
const timestamp = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

let errorMessage = 'Không xác định';
try {
  if (errorData.error) {
    errorMessage = errorData.error.message || JSON.stringify(errorData.error);
  } else if (errorData.message) {
    errorMessage = errorData.message;
  } else {
    errorMessage = JSON.stringify(errorData).substring(0, 500);
  }
} catch(e) {
  errorMessage = 'Không parse được lỗi';
}

// Phát hiện loại lỗi
let errorType = 'UNKNOWN';
let emoji = '❌';
const errLower = errorMessage.toLowerCase();
if (errLower.includes('limit') || errLower.includes('maximum') || errLower.includes('too many')) {
  errorType = 'TAB_LIMIT_REACHED';
  emoji = '🚫';
} else if (errLower.includes('quota') || errLower.includes('rate')) {
  errorType = 'QUOTA_EXCEEDED';
  emoji = '⏱️';
} else if (errLower.includes('permission') || errLower.includes('403')) {
  errorType = 'PERMISSION_DENIED';
  emoji = '🔒';
} else if (errLower.includes('not found') || errLower.includes('404')) {
  errorType = 'SHEET_NOT_FOUND';
  emoji = '🔍';
} else {
  errorType = 'CREATE_TAB_FAILED';
  emoji = '❌';
}

const sheetUrl = 'https://docs.google.com/spreadsheets/d/' + meta.sheetId + '/edit';
const videoLink = meta.videoLink || 'Không có';
const meetingName = meta.meetingName || meta.tabName || 'Không rõ';

const telegramMsg = emoji + ' <b>LỖI TẠO TAB BIÊN BẢN HỌP</b>\n\n' +
  '📋 <b>Cuộc họp:</b> ' + meetingName + '\n' +
  '📅 <b>Ngày:</b> ' + (meta.meetingDateTime || 'Không rõ') + '\n' +
  '🎬 <b>Video:</b> ' + videoLink + '\n\n' +
  '⚠️ <b>Loại lỗi:</b> ' + errorType + '\n' +
  '💬 <b>Chi tiết:</b> ' + errorMessage.substring(0, 300) + '\n\n' +
  '📊 <b>Google Sheets:</b> <a href="' + sheetUrl + '">Mở file</a>\n' +
  '🕐 <b>Thời gian:</b> ' + timestamp + '\n\n' +
  '🔧 <b>Cần xử lý:</b>\n' +
  '1. Kiểm tra file Google Sheets\n' +
  '2. Nếu đầy tab → tạo file mới và cập nhật Sheet ID\n' +
  '3. Chạy lại workflow cho video này';

return [{ json: { telegramMsg, errorType, meetingName, timestamp } }];

const logRow = $('14d. Prepare Log Row').all()[$itemIndex].json;

const now = new Date();
const timestamp = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

const meetingName = logRow.meetingName || 'Không rõ';
const meetingDate = logRow.meetingDate || 'Không rõ';
const duration = logRow.duration || 'Không rõ';
const summaryLink = logRow.summaryLink || 'Không có';
const videoLink = logRow.videoLink || 'Không có';

const telegramMsg = '✅ <b>SUMMARY HOÀN TẤT — ĐÃ TỰ ĐỘNG ĐỒNG BỘ VÀO PORTAL</b>\n\n' +
  '📋 <b>Cuộc họp:</b> ' + meetingName + '\n' +
  '📅 <b>Ngày:</b> ' + meetingDate + '\n' +
  '⏱ <b>Thời lượng:</b> ' + duration + '\n' +
  '🎬 <b>Video:</b> ' + videoLink + '\n\n' +
  '📊 <b>Link Summary (Sheet):</b>\n' + summaryLink + '\n\n' +
  '🕐 <b>Hoàn thành lúc:</b> ' + timestamp;

return [{ json: { telegramMsg } }];

// .all()[$itemIndex] thay vì .first() — tránh lẫn dữ liệu giữa nhiều video
// được xử lý cùng lúc trong 1 lần chạy (xem giải thích chi tiết ở node 1f).
const p = $('14a. Parse Summary').all()[$itemIndex].json;
const rawTranscript = ($('8. Format Transcript').all()[$itemIndex].json.transcript) || '';
const realMeetUrl = $('2b. Save to /tmp').all()[$itemIndex].json.realMeetUrl;

function clean(v) {
  if (!v || v === 'Không đề cập') return undefined;
  return v;
}

// Guard against the model inventing an owner name instead of leaving it
// blank — only keep it if the name actually appears in the raw transcript.
const transcriptLower = rawTranscript.toLowerCase();
function cleanName(v) {
  // Owner có thể là nhiều người ngăn cách dấu phẩy (vd "Nam, Vy") — kiểm tra
  // TỪNG tên riêng lẻ, không kiểm tra cả cụm ghép, vì các tên thường được nói
  // ở những câu khác nhau trong transcript chứ không liền nhau thành 1 cụm.
  const val = clean(v);
  if (!val) return undefined;
  const names = val.split(',').map(s => s.trim()).filter(Boolean);
  const validNames = names.filter(n => transcriptLower.includes(n.toLowerCase()));
  return validNames.length ? validNames.join(', ') : undefined;
}

const recommendedTasks = (p.projectsArr || []).map((pr) => {
  const manday = parseFloat(pr.manday);
  const taskCha = clean(pr.taskCha);
  const kpi = clean(pr.kpi);
  // Gửi riêng taskCha và kpi_output như 2 field độc lập — đúng cấu trúc
  // Sheet đang hiện "Task cha" và "KPI / Output" là 2 dòng riêng biệt.
  return {
    project_name: clean(pr.name),
    detail_task: taskCha || kpi || clean(pr.name) || 'Task từ cuộc họp',
    kpi_output: kpi,
    priority: ['Critical', 'High', 'Normal'].includes(pr.priority) ? pr.priority : 'Normal',
    assigned_name: cleanName(pr.owner),
    deadline: clean(pr.deadline),
    manday_est: isNaN(manday) ? undefined : manday
  };
});

// Giữ riêng "Vấn đề & rủi ro" và "Bước tiếp theo" như trên Sheet, không gộp
// chung vào 1 field "decisions" nữa (decisions vốn dành cho quyết định thật,
// mà n8n flow này không có — để trống).
const issues = (p.issuesArr || []).filter(Boolean);
const nextSteps = (p.nextArr || []).filter(Boolean);

const firstProjectName = p.projectsArr && p.projectsArr[0] ? clean(p.projectsArr[0].name) : undefined;

const durationMinutes = parseFloat(p.duration);
const payload = {
  title: p.meetingName,
  meeting_date: p.meetingDateIso,
  start_time: p.startTimeStr || '09:00',
  duration_minutes: isNaN(durationMinutes) ? undefined : durationMinutes,
  meeting_url: realMeetUrl || p.videoLink,
  platform: 'Google Meet',
  executive_summary: p.overview || p.shortSummary || '',
  decisions: [],
  issues,
  next_steps: nextSteps,
  recommended_tasks: recommendedTasks,
  project_name: firstProjectName || clean(p.teamName) || '',
  team_name: clean(p.teamName),
  organizer_name: clean(p.summarist),
  participant_count: p.speakerCount,
  transcript: rawTranscript,
  sheet_row_id: p.tabName
};

return [{ json: payload }];

const errorData = $input.first().json;
const now = new Date();
const timestamp = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

let errorMessage = 'Không xác định';
try {
  if (errorData.error) {
    errorMessage = typeof errorData.error === 'string'
      ? errorData.error
      : (errorData.error.message || JSON.stringify(errorData.error));
  } else if (errorData.message) {
    errorMessage = errorData.message;
  } else {
    errorMessage = JSON.stringify(errorData).substring(0, 500);
  }
} catch (e) {
  errorMessage = 'Không parse được lỗi';
}

// Best-effort: recover which recording this was, so the alert is actionable
// instead of just "something failed somewhere in the pipeline". Wrapped in
// try/catch since this node can be reached from several different points in
// the pipeline (GDrive download, FFmpeg, AssemblyAI upload/transcribe error,
// Claude Summary), some of which run before '1d. Find New Video' would even
// have a matching item for this $itemIndex in edge cases.
let fileName = 'Không rõ', subfolderName = 'Không rõ';
try {
  const video = $('1d. Find New Video').all()[$itemIndex].json;
  fileName = video.name || fileName;
  subfolderName = video.subfolderName || subfolderName;
} catch (e) {}

const telegramMsg = '🔥 <b>LỖI PIPELINE XỬ LÝ MEETING</b>\n\n' +
  '🎬 <b>File:</b> ' + fileName + '\n' +
  '📁 <b>Thư mục:</b> ' + subfolderName + '\n\n' +
  '💬 <b>Chi tiết lỗi:</b> ' + errorMessage.substring(0, 400) + '\n\n' +
  '🕐 <b>Thời gian:</b> ' + timestamp + '\n\n' +
  '⚠️ Cuộc họp này sẽ KHÔNG được tự động tóm tắt/đồng bộ tiếp — cần kiểm tra n8n execution history và chạy lại thủ công cho recording này.';

return [{ json: { telegramMsg } }];
